result:
    .mobile-page{
		background: #f5f5f5
		font-size: 12px
		.live-broadcast{
			padding: 10px;
			background-color: #fff;
			&.on{
				padding-right: 0;
			}
		}
	}
	.live-wrapper-d{
		width: 100%;
		.live-item-d{
			.img-box{
				width: 100%;
				height: 335px;
				position: relative;
				background: #F3F9FF;
				.empty-box{
					width: 100%;
					height: 265px;
					background-color: unset;

					img {
						width: 88px;
						height: 68px;
					}
				}
				.label{
					top:12px;
					left:0;
					border-radius: 0 50px 50px 0;
					height: 20px;
				}
				.info{
					position: absolute;
					width: 100%;
					background-color: rgba(0,0,0,0.2);
					left:0;
					bottom: 0;
					padding: 12px;
					.title{
						color: #FFFFFF;
						font-size: 14px;
					}
					.people{
						display: flex;
						align-items: center;
						margin-top: 6px;
						img {
							width: 20px;
							height: 20px;
							border-radius: 50%;
							margin-right: 5px;
						}
						span {
							font-size: 12px;
							color: #FFFFFF;
						}
					}
				}
			}
			&.on{
				width: 100%;
				border-radius: 8px;
				border:1px solid #eee;
				padding: 10px;
				margin-top: 10px;
				.name{
					color: #333333;
					font-size: 14px;
					display: flex;
					align-items: center;

					.label{
						position: unset;
						width: 32px;
						height: 16px;
						text-align: center;
						line-height: 16px;
						background: linear-gradient(90deg, #208FF2 0%, #3FA6FF 98%);
						border-radius: 3px;
						margin-right: 8px;
						&.bggary{
							background: linear-gradient(90deg, #6D80AC 0%, #889EBD 100%);
						}
					}
				}
				.people{
					font-size: 12px;
					color: #999999;
					display: flex;
					align-items: center;
					margin-top: 6px;

					img {
						width: 20px;
						height: 20px;
						border-radius: 50%;
						margin-right: 6px;
					}

					.line {
						width: 1px;
						height: 11px;
						background: #eee;
						margin: 0 6px;
					}

				}
			}
		}
	}
	.live-wrapper-c{
		width: 100%;
		.live-item-a{
			position: relative;
			&:nth-last-child(1){
				margin-bottom: 0 !important
			}
			.empty-box{
				width: 100%;
				height: 200px;
				background: #F3F9FF;
				img {
					width: 88px;
					height: 68px;
				}
			}
			.img-box{
				.label{
					height: 20px;
					line-height: 20px;
					border-radius: 0 50px 50px 0;
					left:0;
					top:12px;
					&.bgred{
					   width: 65px;
					   background: linear-gradient(90deg, #FF2851 0%, #FF2851 100%);
					}
					&.bgblue{
						.txt{
							border-radius: 0 50px 50px 0
							line-height: 20px;
						}
						.msg{
							height: 100%;
						}
					}
					&.bggary{
						width: 38px;
					}
				}
			}
			.info{
				.title{
					color: #333333;
					font-size: 14px;
					margin-top: 12px;
				}
				.people{
					display: flex;
					align-items: center;
					font-size: 12px;
					color: #999999;
					margin-top: 6px;

					img {
						width: 20px;
						height: 20px;
						background: #F3F9FF;
						border-radius: 50%;
						margin-right: 6px;
					}
				}
			}
		}
	}
    .live-wrapper-a{
		.live-item-a{
			display: flex
			align-items: center;
			position: relative
			margin-bottom: 10px
			overflow: hidden
			&:nth-last-child(1){
				margin-bottom: 0 !important
			}
			.img-box{
				position: relative
				width: 166px
				height: 118px
				overflow: hidden
				.empty-box{
					background-color: #F3F9FF;
					img {
						width: 65px;
						height: 50px;
					}
				}
				.bggary.label{
					width: 34px;
					line-height: 18px;
				}
			}
			.info{
				flex: 1
				overflow: hidden
				margin-left: 10px;
				.title{
					color: #333333
					font-size: 14px
				}
			}
			.goods-wrapper{
				margin-top: 8px
				display: flex
				.goods-item{
					position: relative
					width: 48px
					height: 48px
					border-radius: 4px;
					margin-right: 8px;
					background: #F3F9FF;
					display: flex;
					align-items: center;
					justify-content: center;


					&:nth-child(3n){
						margin-right: 0
					}
					img {
						width: 36px;
						height: 28px;
					}
					span {
						position: absolute
						left: 0
						bottom: 0
						color: #fff
						font-size: 12px
						width: 100%;
						height: 13px;
						background: rgba(0,0,0,0.3);
						border-radius: 0 0 4px 4px;
						font-size: 11px;
						text-align: center;
						line-height: 14px;

						&.num{
							width: 100%;
							height: 100%;
							background: rgba(0,0,0,0.35);
							font-size: 14px;
							color: #FEFEFE;
							border-radius: 4px;
							line-height: 48px;
						}
					}
				}
			}
		}
	}

    .live-wrapper-b{
		display: flex;
		overflow: hidden;

		.live-item-b{
			width: 140px
			margin-right: 10px;
			&:nth-last-child(1){
				margin-bottom: 0
			}

			.img-box{
				position: relative
				height: 100px
				width: 140px;
				.empty-box{
					background: #F3F9FF;
					img {
						width: 65px;
						height: 50px;
					}
				}
			}
			.label{
				top:0;
				left:0;

				&.bgred{
					width: 61px;
				}
				&.bgblue{
					width: 128px;
					.txt{
						border-radius: 0
					}
				}
				&.bggary{
					width: 34px;
				}
			}
			.info{
				width: 100%
				.title{
					font-size: 14px;
					color: #333;
					margin-top: 6px;
				}
				.people{
					display: flex
					align-items: center
					margin-top: 6px;
					font-size: 12px;
					color: #999;
					img {
						width: 20px
						height: 20px
						margin-right: 5px
						border-radius: 50%
					}
				}
			}
		}
	}
    .bggary{
		background: linear-gradient(90deg, #6D80AC 0%, #889EBD 100%);
	}
    .bgred{
		background: linear-gradient(90deg, #FF2851 0%, #FF2851 100%);
	}
    .label{
		display: flex
		align-items: center
		justify-content: center
		position: absolute
		left: 6px
		top: 6px
		width: 61px;
		height: 18px;
		line-height: 18px;
		border-radius: 50px;
		color: #fff
		font-size: 11px
		.iconfont-diy{
			font-size: 12px;
			margin-right: 5px
		}
		&.bgblue{
			justify-content: inherit
			width: 128px
			background: rgba(0,0,0,0.2)
			overflow: hidden
			.txt{
				width: 34px
				height: 100%
				text-align: center
				margin-right: 7px
				background: linear-gradient(90deg, #208FF2 0%, #3FA6FF 98%);
				border-radius: 50px;
				line-height: 18px;
			}
		}
		&.bggary{
			width: 54px
		}
	}
